<template><section aria-label="编码转换"><p class="tool-note">按 UTF-8 处理文本。URL 组件编码适合参数值，完整 URL 编码会保留地址分隔符；解码不会把 + 当作空格。Unicode 模式使用带双引号的 JSON 字符串转义。</p><div class="tool-actions"><label>方式<select v-model="mode" aria-label="编码方式"><option value="url-component">URL 参数组件</option><option value="url">完整 URL</option><option value="base64">Base64</option><option value="base64url">Base64URL</option><option value="unicode">Unicode / JSON 转义</option></select></label><button type="button" @click="run(false)">编码</button><button type="button" @click="run(true)">解码</button><button type="button" :disabled="!output" @click="input=output;output='';message=''">结果作为输入</button></div><div class="tool-two-column"><label class="tool-label">编码输入<textarea v-model="input" aria-label="编码输入" spellcheck="false"></textarea></label><label class="tool-label">编码结果<textarea v-model="output" aria-label="编码结果" readonly spellcheck="false"></textarea></label></div><div class="tool-actions"><button type="button" :disabled="!output" @click="copy">复制编码结果</button><button type="button" @click="input='';output='';message=''">清空编码内容</button></div><p role="status">{{ message }}</p></section></template>
<script>
import { transformEncoding } from '../../utils/extended-tools.mjs';
export default {name:'EncodingTool',data:()=>({input:'',output:'',mode:'url-component',message:''}),methods:{run(decode){try{this.output=transformEncoding(this.input,this.mode,decode);this.message=decode?'解码完成':'编码完成';}catch(error){this.output='';this.message='转换失败：'+error.message;}},async copy(){try{await navigator.clipboard.writeText(this.output);this.message='已复制编码结果';}catch{this.message='复制未完成，请选择文字手动复制';}}}};
</script>
